		apiClient := client.NewAPIClient(config)
		apiClient.GetConfig().HTTPClient = server.Client()
		api := (*AgentToAgentTestsAPIService)(&apiClient.Common)

		_, httpResponse, err := api.UpdateAgentToAgentTest(testId).AgentToAgentTestRequest(requestBody).Aid(aid).Expand(expand).Execute()
		if err == nil {
			t.Fatalf("UpdateAgentToAgentTest() error = nil, want *GenericAPIError")
		}
		if httpResponse == nil {
			t.Fatal("UpdateAgentToAgentTest() returned a nil HTTP response")
		}
		if httpResponse.StatusCode != responseStatus {
			t.Errorf("UpdateAgentToAgentTest() status = %d, want %d", httpResponse.StatusCode, responseStatus)
		}

		var apiError *internalerror.GenericAPIError
		if !errors.As(err, &apiError) {
			t.Fatalf("UpdateAgentToAgentTest() error type = %T, want *GenericAPIError", err)
		}
		if !reflect.DeepEqual(apiError.Body, responseBodyJSON) {
			t.Errorf("GenericAPIError.Body = %q, want %q", apiError.Body, responseBodyJSON)
		}
		if !reflect.DeepEqual(apiError.Model, expectedModel) {
			t.Errorf("GenericAPIError.Model = %#v, want %#v", apiError.Model, expectedModel)
		}

		expectedErrorMessage := internalerror.FormatErrorMessage(
			httpResponse.Status,
			string(responseBodyJSON),
			expectedModel,
		)
		if apiError.ErrorMessage != expectedErrorMessage {
			t.Errorf(
				"GenericAPIError.ErrorMessage = %q, want %q",
				apiError.ErrorMessage,
				expectedErrorMessage,
			)
		}
